/** The collections of the database, as Mongoose models. They reflect it: Mongoose never creates collections or indexes with them. */
import { Schema, type Connection, type Model } from 'mongoose'

/** A document as the driver gives it, by the stored names of its fields */
export type Stored = Record<string, unknown>

/** The model of every collection */
export interface Models {
  authors: Model<Stored>
  posts: Model<Stored>
}

/** Defines the model of every collection on `connection`. */
export function defineModels(connection: Connection): Models {
  /** The 'authors' collection. */
  const authors = new Schema(
    {
      _id: Schema.Types.UUID,
      email: { type: String, required: true },
    },
    { collection: 'authors', versionKey: false, minimize: false, autoIndex: false, autoCreate: false },
  )

  /** The 'posts' collection. */
  const posts = new Schema(
    {
      _id: Schema.Types.UUID,
      title: { type: String, required: true },
      author: { type: Schema.Types.UUID, required: true },
      published_at: Date,
      comments: { type: [new Schema({ id: { type: Schema.Types.UUID, required: true }, text: { type: String, required: true }, marks: { type: [Schema.Types.UUID], default: undefined, required: true } }, { _id: false, strict: false, minimize: false })], default: undefined, required: true },
    },
    { collection: 'posts', versionKey: false, minimize: false, autoIndex: false, autoCreate: false },
  )
  posts.index({ author: 1 }, { name: 'ix_posts_author' })

  return {
    authors: connection.model<Stored>('Author', authors as unknown as Schema<Stored>),
    posts: connection.model<Stored>('Post', posts as unknown as Schema<Stored>),
  }
}

