/** Repository of the "authors" table: reads and writes rows, and decides nothing. */
import type { ClientSession } from 'mongoose'
import { plain, refusal, type Db } from '../database.js'
import { Author } from '../entities/author.js'
import type { Stored } from '../models.js'
import type { Page } from '../paging.js'

/** Where authors rows are kept. Services depend only on this interface. */
export interface AuthorRepository {
  findById(id: string): Promise<Author | null>
  list(offset?: number, limit?: number): Promise<Page<Author>>
  insert(entity: Author): Promise<Author>
  update(entity: Author): Promise<Author>
  delete(entity: Author): Promise<void>
}

/** The key of a row, as a list of its key values. */
function keyOf(row: Author): unknown[] {
  return [row.id]
}

/** Orders two keys value by value. */
function compareKeys(a: unknown[], b: unknown[]): number {
  for (let index = 0; index < a.length; index++) {
    const x = a[index] as number | string
    const y = b[index] as number | string
    if (x < y) return -1
    if (x > y) return 1
  }
  return 0
}

/** The values each entity was read with, by the stored names of its fields: a change writes only those that differ. */
const loaded = new WeakMap<Author, Record<string, string>>()

/** The fields of an entity a change may write. */
function changeable(entity: Author): Stored {
  return {
    email: entity.email,
  }
}

/** The same fields as text, to compare them later. */
const snapshot = (entity: Author): Record<string, string> =>
  Object.fromEntries(Object.entries(changeable(entity)).map(([name, value]) => [name, JSON.stringify(value ?? null)]))

/** The Author of a document; a field it does not have is null. */
function toEntity(document: Stored): Author {
  const entity = Object.assign(new Author(), {
    id: (plain(document._id) ?? null) as string,
    email: (plain(document.email) ?? null) as string,
  })
  loaded.set(entity, snapshot(entity))
  return entity
}

/** The fields of a new document; those left empty are not stored, and take their default. */
function storedValues(entity: Author): Stored {
  const values: Stored = {
    _id: entity.id,
    email: entity.email,
  }
  return Object.fromEntries(Object.entries(values).filter(([, value]) => value !== undefined && value !== null))
}

/** What a change writes and what it removes: only the fields that are not as they were read. */
function changesOf(entity: Author): { $set: Stored; $unset: Stored } {
  const before = loaded.get(entity)
  const $set: Stored = {}
  const $unset: Stored = {}
  for (const [name, value] of Object.entries(changeable(entity))) {
    if (before?.[name] === JSON.stringify(value ?? null)) continue
    if (value === undefined || value === null) $unset[name] = ''
    else $set[name] = value
  }
  return { $set, $unset }
}

/** Keeps authors documents in the database, through Mongoose. Every write is stored at once. */
export class MongoAuthorRepository implements AuthorRepository {
  constructor(
    private readonly db: Db,
    private readonly session: ClientSession | null = null,
  ) {}

  /** The row with this primary key, or null. */
  async findById(id: string): Promise<Author | null> {
    const foundDocument = await this.db.models.authors.findOne({ _id: id }).session(this.session).lean<Stored>()
    return foundDocument === null ? null : toEntity(foundDocument)
  }

  /** At most `limit` rows from `offset`, by primary key, and how many there are. */
  async list(offset: number = 0, limit: number = 50): Promise<Page<Author>> {
    const documents = await this.db.models.authors.find({}).sort({ _id: 1 }).skip(offset).limit(limit).session(this.session).lean<Stored[]>()
    const total = await this.db.models.authors.countDocuments({}).session(this.session)
    return { items: documents.map(toEntity), total, offset, limit }
  }

  /** Stores a new row; the values the database fills are read back. */
  async insert(entity: Author): Promise<Author> {
    try {
      const [document] = await this.db.models.authors.create([storedValues(entity)], { session: this.session ?? undefined })
      const stored = toEntity(document.toObject() as Stored)
      Object.assign(entity, stored)
      loaded.set(entity, loaded.get(stored)!)
      return entity
    } catch (error) {
      throw refusal('Author', error)
    }
  }

  /** Stores the changes made to a row read from this repository. */
  async update(entity: Author): Promise<Author> {
    try {
      await this.db.models.authors.updateOne({ _id: entity.id }, changesOf(entity), { session: this.session ?? undefined, runValidators: true, timestamps: false })
    } catch (error) {
      throw refusal('Author', error)
    }
    loaded.set(entity, snapshot(entity))
    return entity
  }

  /** Removes a row read from this repository. */
  async delete(entity: Author): Promise<void> {
    try {
      await this.db.models.authors.deleteOne({ _id: entity.id }).session(this.session)
    } catch (error) {
      throw refusal('Author', error)
    }
  }
}

/** Keeps authors rows in memory, for tests and for trying the services without a database. */
export class MemoryAuthorRepository implements AuthorRepository {
  private readonly rows = new Map<string, Author>()

  private visible(): Author[] {
    return [...this.rows.values()].filter((row) => true).sort((a, b) => compareKeys(keyOf(a), keyOf(b)))
  }

  /** The row with this primary key, or null. */
  async findById(id: string): Promise<Author | null> {
    return this.visible().find((row) => row.id === id) ?? null
  }

  /** At most `limit` rows from `offset`, by primary key, and how many there are. */
  async list(offset: number = 0, limit: number = 50): Promise<Page<Author>> {
    const rows = this.visible()
    return { items: rows.slice(offset, offset + limit), total: rows.length, offset, limit }
  }

  /** Stores a new row; the values the database fills are read back. */
  async insert(entity: Author): Promise<Author> {
    this.rows.set(JSON.stringify(keyOf(entity)), entity)
    return entity
  }

  /** Stores the changes made to a row read from this repository. */
  async update(entity: Author): Promise<Author> {
    this.rows.set(JSON.stringify(keyOf(entity)), entity)
    return entity
  }

  /** Removes a row read from this repository. */
  async delete(entity: Author): Promise<void> {
    this.rows.delete(JSON.stringify(keyOf(entity)))
  }
}

