  async insert(entity: Post): Promise<Post> {
    try {
      const [document] = await this.db.models.posts.create([storedValues(entity)], { session: this.session ?? undefined })
      const stored = toEntity(document.toObject() as Stored)
      Object.assign(entity, stored)
      loaded.set(entity, loaded.get(stored)!)
      return entity
    } catch (error) {
      throw refusal('Post', error)
    }
  }

  /** Stores the changes made to a row read from this repository. */
  async update(entity: Post): Promise<Post> {
    try {
      await this.db.models.posts.updateOne({ _id: entity.id }, changesOf(entity), { session: this.session ?? undefined, runValidators: true, timestamps: false })
    } catch (error) {
      throw refusal('Post', error)
    }
    loaded.set(entity, snapshot(entity))
    return entity
  }

  /** Removes a row read from this repository. */
  async delete(entity: Post): Promise<void> {
    try {
      await this.db.models.posts.deleteOne({ _id: entity.id }).session(this.session)
    } catch (error) {
      throw refusal('Post', error)
    }
  }

  /** Adds an item to comments, and returns the row as it is then, or null when there is none. */
  async addComment(id: string, comment: { id: string; text: string; marks: string[] }): Promise<Post | null> {
    let changed: Stored | null
    try {
      changed = await this.db.models.posts
        .findOneAndUpdate({ _id: id }, { $push: { comments: comment } }, { returnDocument: 'after', runValidators: true, timestamps: false })
        .session(this.session)
        .lean<Stored>()
    } catch (error) {
      throw refusal('Post', error)
    }
    return changed === null ? null : toEntity(changed)
  }

  /** Removes an item from comments that has this size, and returns the row as it is then, or null when there is none. */
  async removeComment(id: string, position: number, size: number): Promise<Post | null> {
    let changed: Stored | null
    try {
      changed = await this.db.models.posts
        .findOneAndUpdate({ _id: id, comments: { $size: size } }, [{ $set: { comments: { $concatArrays: [{ $slice: ['$comments', position] }, { $slice: ['$comments', position + 1, size] }] } } }], { returnDocument: 'after', runValidators: true, timestamps: false })
        .session(this.session)
        .lean<Stored>()
    } catch (error) {
      throw refusal('Post', error)
    }
    return changed === null ? null : toEntity(changed)
  }
}

/** Keeps posts rows in memory, for tests and for trying the services without a database. */
export class MemoryPostRepository implements PostRepository {
  private readonly rows = new Map<string, Post>()

  private visible(): Post[] {
    return [...this.rows.values()].filter((row) => true).sort((a, b) => compareKeys(keyOf(a), keyOf(b)))
  }

  /** The row with this primary key, or null. */
  async findById(id: string): Promise<Post | null> {
    return this.visible().find((row) => row.id === id) ?? null
  }

  /** At most `limit` rows from `offset`, by primary key, and how many there are. */
  async list(offset: number = 0, limit: number = 50): Promise<Page<Post>> {
    const rows = this.visible()
    return { items: rows.slice(offset, offset + limit), total: rows.length, offset, limit }
  }

  /** Rows with this author, by primary key. */
  async listByAuthor(author: string): Promise<Post[]> {
    return this.visible().filter((row) => row.author === author)
  }

  /** Stores a new row; the values the database fills are read back. */
  async insert(entity: Post): Promise<Post> {
    this.rows.set(JSON.stringify(keyOf(entity)), entity)
    return entity
  }

  /** Stores the changes made to a row read from this repository. */
  async update(entity: Post): Promise<Post> {
    this.rows.set(JSON.stringify(keyOf(entity)), entity)
    return entity
  }

  /** Removes a row read from this repository. */
  async delete(entity: Post): Promise<void> {
    this.rows.delete(JSON.stringify(keyOf(entity)))
  }

  /** Adds an item to comments, and returns the row as it is then, or null when there is none. */
  async addComment(id: string, comment: { id: string; text: string; marks: string[] }): Promise<Post | null> {
    const row = this.visible().find((row) => row.id === id)
    if (row === undefined) return null
    row.comments = [...(row.comments ?? []), comment]
    return row
  }

  /** Removes an item from comments that has this size, and returns the row as it is then, or null when there is none. */
  async removeComment(id: string, position: number, size: number): Promise<Post | null> {
    const row = this.visible().find((row) => row.id === id)
    if (row === undefined) return null
    if ((row.comments ?? []).length !== size) return null
    row.comments = (row.comments ?? []).filter((_, index) => index !== position)
    return row
  }
}

