/** Operations on authors: what each one checks before it writes. */
import { Author } from '../entities/author.js'
import { ConflictError, NotFoundError, ValidationFailedError, type FieldError } from '../errors.js'
import type { Page } from '../paging.js'
import type { UnitOfWork } from '../unit-of-work.js'

/** Properties a client may send: the database fills the others */
const FIELDS = new Set(['id', 'email'])

/** Operations on authors. Repositories commit every write. */
export class AuthorService {
  constructor(private readonly uow: UnitOfWork) {}

  /** Checks the values against the rules of the "authors" table, and the rows they point to; throws ValidationFailedError with every problem. */
  private async validate(uow: UnitOfWork, values: Partial<Record<string, unknown>>, current: Author | null): Promise<void> {
    const creating = current === null
    const errors: FieldError[] = []
    for (const name of Object.keys(values)) if (!FIELDS.has(name)) errors.push({ field: name, message: 'is not a field of Author' })
    if (!creating) for (const name of Object.keys(values)) if (['id'].includes(name)) errors.push({ field: name, message: 'cannot be changed' })
    {
      const value = values.id
      if (value == null) {
        if (creating || 'id' in values) errors.push({ field: '_id', message: 'is required' })
      }
    }
    {
      const value = values.email
      if (value == null) {
        if (creating || 'email' in values) errors.push({ field: 'email', message: 'is required' })
      }
    }
    if (errors.length > 0) throw new ValidationFailedError('Author', errors)
  }

  /** Every check before a write: the values, the rows they point to, the unique values. */
  private async check(uow: UnitOfWork, values: Partial<Record<string, unknown>>, current: Author | null): Promise<void> {
    await this.validate(uow, values, current)
  }

  /** The Author with this key; NotFoundError when there is none. */
  private async find(uow: UnitOfWork, id: string): Promise<Author> {
    const entity = await uow.authors.findById(id)
    if (entity === null) throw new NotFoundError('Author', id)
    return entity
  }

  /** Stores a new Author after checking it. */
  async createAuthor(author: Author): Promise<Author> {
    const values: Partial<Record<string, unknown>> = Object.fromEntries([...FIELDS].map((field) => [field, (author as unknown as Record<string, unknown>)[field]]))
    return this.uow.transaction(async (uow) => {
      await this.check(uow, values, null)
      const created = await uow.authors.insert(author)
      return created
    })
  }

  /** The Author with this key; NotFoundError when there is none. */
  async getAuthor(id: string): Promise<Author> {
    return await this.find(this.uow, id)
  }

  /** A page of authors, by primary key. */
  async listAuthors(offset = 0, limit = 50): Promise<Page<Author>> {
    return this.uow.authors.list(offset, limit)
  }

  /** Changes the given values of a Author. */
  async updateAuthor(id: string, changes: Partial<Author>): Promise<Author> {
    const values: Partial<Record<string, unknown>> = Object.fromEntries(Object.entries(changes).filter(([, value]) => value !== undefined))
    return this.uow.transaction(async (uow) => {
      const current = await this.find(uow, id)
      await this.check(uow, values, current)
      Object.assign(current, values)
      const updated = await uow.authors.update(current)
      return updated
    })
  }

  /** Deletes a Author. */
  async deleteAuthor(id: string): Promise<void> {
    return this.uow.transaction(async (uow) => {
      const current = await this.find(uow, id)
      if ((await uow.posts.listByAuthor(current.id)).length > 0) throw new ConflictError('Author', 'rows of posts still point to it', ['posts'])
      await uow.authors.delete(current)
    })
  }
}

