const FIELDS = new Set(['id', 'title', 'author', 'publishedAt', 'comments'])

/** The rules of the documents and lists inside each one */
const DOCUMENTS = {
  comments: { items: { fields: { id: { required: true }, text: { required: true }, marks: { required: true, items: {} } } } },
} satisfies Record<string, Rule>

/** Operations on posts. Repositories commit every write. */
export class PostService {
  constructor(private readonly uow: UnitOfWork) {}

  /** Checks the values against the rules of the "posts" table, and the rows they point to; throws ValidationFailedError with every problem. */
  private async validate(uow: UnitOfWork, values: Partial<Record<string, unknown>>, current: Post | null): Promise<void> {
    const creating = current === null
    const errors: FieldError[] = []
    for (const name of Object.keys(values)) if (!FIELDS.has(name)) errors.push({ field: name, message: 'is not a field of Post' })
    if (!creating) for (const name of Object.keys(values)) if (['id'].includes(name)) errors.push({ field: name, message: 'cannot be changed' })
    {
      const value = values.id
      if (value == null) {
        if (creating || 'id' in values) errors.push({ field: '_id', message: 'is required' })
      }
    }
    {
      const value = values.title
      if (value == null) {
        if (creating || 'title' in values) errors.push({ field: 'title', message: 'is required' })
      }
    }
    {
      const value = values.author
      if (value == null) {
        if (creating || 'author' in values) errors.push({ field: 'author', message: 'is required' })
      }
    }
    {
      const value = values.comments
      if (value == null) {
        if (creating || 'comments' in values) errors.push({ field: 'comments', message: 'is required' })
      } else {
        errors.push(...problems(value, DOCUMENTS.comments, 'comments'))
      }
    }
    {
      const author = 'author' in values ? values.author : current?.author
      if (author != null && (await uow.authors.findById(author as string)) === null)
        errors.push({ field: 'author', message: 'no Author has this key' })
    }
    if (errors.length > 0) throw new ValidationFailedError('Post', errors)
  }

  /** Every check before a write: the values, the rows they point to, the unique values. */
  private async check(uow: UnitOfWork, values: Partial<Record<string, unknown>>, current: Post | null): Promise<void> {
    await this.validate(uow, values, current)
  }

  /** The Post with this key; NotFoundError when there is none. */
  private async find(uow: UnitOfWork, id: string): Promise<Post> {
    const entity = await uow.posts.findById(id)
    if (entity === null) throw new NotFoundError('Post', id)
    return entity
  }

  /** Stores a new Post after checking it. */
  async createPost(post: Post): Promise<Post> {
    const values: Partial<Record<string, unknown>> = Object.fromEntries([...FIELDS].map((field) => [field, (post as unknown as Record<string, unknown>)[field]]))
    return this.uow.transaction(async (uow) => {
      await this.check(uow, values, null)
      const created = await uow.posts.insert(post)
      return created
    })
  }

  /** The Post with this key; NotFoundError when there is none. */
  async getPost(id: string): Promise<Post> {
    return await this.find(this.uow, id)
  }

  /** A page of posts, by primary key. */
  async listPosts(offset = 0, limit = 50): Promise<Page<Post>> {
    return this.uow.posts.list(offset, limit)
  }

  /** Changes the given values of a Post. */
  async updatePost(id: string, changes: Partial<Post>): Promise<Post> {
    const values: Partial<Record<string, unknown>> = Object.fromEntries(Object.entries(changes).filter(([, value]) => value !== undefined))
    return this.uow.transaction(async (uow) => {
      const current = await this.find(uow, id)
      await this.check(uow, values, current)
      Object.assign(current, values)
      const updated = await uow.posts.update(current)
      return updated
    })
  }

  /** Deletes a Post. */
  async deletePost(id: string): Promise<void> {
    return this.uow.transaction(async (uow) => {
      const current = await this.find(uow, id)
      await uow.posts.delete(current)
    })
  }

  /** The posts with this author. */
  async listPostsByAuthor(author: string): Promise<Post[]> {
    return await this.uow.posts.listByAuthor(author)
  }

  /** Adds an item to comments. */
  async addComment(id: string, comment: { id: string; text: string; marks: string[] }): Promise<Post> {
    const errors = problems([comment], DOCUMENTS.comments, 'comments')
    if (errors.length > 0) throw new ValidationFailedError('Post', errors)
    return this.uow.transaction(async (uow) => {
      await this.find(uow, id)
      const updated = await uow.posts.addComment(id, comment)
      if (updated === null) throw new NotFoundError('Post', id)
      return updated
    })
  }

  /** Removes an item from comments, by its position. */
  async removeComment(id: string, position: number): Promise<Post> {
    return this.uow.transaction(async (uow) => {
      const current = await this.find(uow, id)
      if (!(position in (current.comments ?? []))) throw new NotFoundError('Comment', position)
      const updated = await uow.posts.removeComment(id, position, (current.comments ?? []).length)
      if (updated === null) throw new ConflictError('Post', 'was changed by someone else since it was read', ['comments'])
      return updated
    })
  }
}

