    const found = await service.getPost(created.id)
    expect(found.id).toEqual(created.id)
  })

  it('refuses a missing value', async () => {
    const uow = new MemoryUnitOfWork()
    const service = new PostService(uow)
    const n = 100
    const parent0 = await addAuthor(uow, n)
    const error: unknown = await service.createPost(newPost(1, { author: parent0.id, id: null as never })).catch((caught: unknown) => caught)
    expect(error).toBeInstanceOf(ValidationFailedError)
    expect((error as ValidationFailedError).errors.map((item) => item.field)).toEqual(['_id'])
  })

  it('refuses a missing parent', async () => {
    const uow = new MemoryUnitOfWork()
    const service = new PostService(uow)
    const n = 100
    const parent0 = await addAuthor(uow, n)
    const error: unknown = await service.createPost(newPost(1, { author: '00000000-0000-4000-8000-000000999999' })).catch((caught: unknown) => caught)
    expect(error).toBeInstanceOf(ValidationFailedError)
    expect((error as ValidationFailedError).errors.map((item) => item.field)).toContain('author')
  })

