  it('adds and removes one item of comments', async () => {
    const uow = new MemoryUnitOfWork()
    const service = new PostService(uow)
    const n = 100
    const parent0 = await addAuthor(uow, n)
    const created = await service.createPost(newPost(1, { author: parent0.id }))
    const before = created.comments?.length ?? 0
    const item = ((n: number) => ({ id: `00000000-0000-4000-8000-${String(n).padStart(12, '0')}`, text: `text-${n}`, marks: [] }))(7)
    const added = await service.addComment(created.id, item)
    expect(added.comments).toHaveLength(before + 1)
    const removed = await service.removeComment(created.id, added.comments!.length - 1)
    expect(removed.comments).toHaveLength(before)
    await expect(service.removeComment(created.id, 99)).rejects.toBeInstanceOf(NotFoundError)
  })

